// fill: a saddle: four lines between (0, 0, 0), (20, 0, 5), (20, 20, 0), (0, 20, 5), each drawn on an upright plane
export function c004(context is Context, id is Id)
{
    const e1 = newSketchOnPlane(context, id + "e1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(e1, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(20, 5) * millimeter });
    skSolve(e1);
    const e2 = newSketchOnPlane(context, id + "e2", { "sketchPlane" : plane(vector(20, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skLineSegment(e2, "l1", { "start" : vector(0, 5) * millimeter, "end" : vector(20, 0) * millimeter });
    skSolve(e2);
    const e3 = newSketchOnPlane(context, id + "e3", { "sketchPlane" : plane(vector(0, 20, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(e3, "l1", { "start" : vector(20, 0) * millimeter, "end" : vector(0, 5) * millimeter });
    skSolve(e3);
    const e4 = newSketchOnPlane(context, id + "e4", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skLineSegment(e4, "l1", { "start" : vector(20, 5) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(e4);
    fill(context, id + "fill1", { "edges" : [{ "entities" : qUnion([qOwnedByBody(qBodyType(qCreatedBy(id + "e1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), qOwnedByBody(qBodyType(qCreatedBy(id + "e2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), qOwnedByBody(qBodyType(qCreatedBy(id + "e3", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), qOwnedByBody(qBodyType(qCreatedBy(id + "e4", EntityType.BODY), BodyType.WIRE), EntityType.EDGE)]), "continuity" : GeometricContinuity.G0 }], "surfaceOperationType" : NewSurfaceOperationType.NEW });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "fill1", EntityType.BODY), BodyType.SHEET)) };
}

// sheet-metal-flat: a channel (flanges on both long edges), a 4 x 50 slot across both bends cut in its flat pattern
export function c005(context is Context, id is Id)
{
    smChannel(context, id + "channel");
    const flatPlane = evPlane(context, { "face" : qCorrespondingInFlat(qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "channel" + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 2) * millimeter)) });
    const f = newSketch(context, id + "f", { "sketchPlane" : qCorrespondingInFlat(qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "channel" + "sm1", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 2) * millimeter)) });
    skRectangle(f, "r", { "firstCorner" : vector(-2, -25) * millimeter, "secondCorner" : vector(2, 25) * millimeter });
    skSolve(f);
    extrude(context, id + "flat1", { "bodyType" : ExtendedToolBodyType.SOLID, "entities" : qSketchRegion(id + "f"), "domain" : OperationDomain.FLAT, "flatOperationType" : FlatOperationType.REMOVE, "endBound" : BoundingType.BLIND, "depth" : 2 * millimeter });
    return { "flatPlane" : { "origin" : round6(flatPlane.origin), "normal" : flatPlane.normal, "x" : flatPlane.x }, "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "channel" + "sm1", EntityType.BODY), BodyType.SOLID)) };
}

