// loft: squares of 20, 14 and 10 mm at 0, 10 and 25 mm, tangent to the first profile
export function c008(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "r", { "firstCorner" : vector(-10, -10) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 10) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s2, "r", { "firstCorner" : vector(-7, -7) * millimeter, "secondCorner" : vector(7, 7) * millimeter });
    skSolve(s2);
    const s3 = newSketchOnPlane(context, id + "s3", { "sketchPlane" : plane(vector(0, 0, 25) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s3, "r", { "firstCorner" : vector(-5, -5) * millimeter, "secondCorner" : vector(5, 5) * millimeter });
    skSolve(s3);
    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "s1") }, { "sheetProfileEntities" : qSketchRegion(id + "s2") }, { "sheetProfileEntities" : qSketchRegion(id + "s3") }], "startCondition" : LoftEndDerivativeType.TANGENT_TO_PROFILE, "startMagnitude" : 1 });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID)) };
}
